{"description":"Inspect dataset structure","cmd":"cd /app && python -c "
import torch
d = torch.load('dataset.pt', map_location='cpu', weights_only=False)
if isinstance(d, dict):
    print('Dict with keys:', list(d.keys()))
    for k, v in d.items():
        if hasattr(v, 'shape'):
            print(k, type(v), list(v.shape))
        else:
            print(k, type(v))
elif isinstance(d, (list, tuple)):
    print('list/tuple len', len(d))
    for i, x in enumerate(d):
        if hasattr(x, 'shape'):
            print(i, type(x), list(x.shape))
        else:
            print(i, type(x))
else:
    print(type(d))
""}
